-- ---------------------------------------------------------------------
-- Revisión: filas esperadas por tabla con los datos de este archivo.
-- ---------------------------------------------------------------------
SELECT 'BRANDS' AS TABLA, COUNT(*) AS FILAS, 17 AS ESPERADAS FROM BRANDS
UNION ALL SELECT 'CATEGORIES', COUNT(*), 7 FROM CATEGORIES
UNION ALL SELECT 'USERS', COUNT(*), 6 FROM USERS
UNION ALL SELECT 'DEPARTMENTS', COUNT(*), 3 FROM DEPARTMENTS
UNION ALL SELECT 'MUNICIPALITIES', COUNT(*), 5 FROM MUNICIPALITIES
UNION ALL SELECT 'NEIGHBORHOODS', COUNT(*), 10 FROM NEIGHBORHOODS
UNION ALL SELECT 'USER_ADDRESSES', COUNT(*), 4 FROM USER_ADDRESSES
UNION ALL SELECT 'PARTNERS', COUNT(*), 6 FROM PARTNERS
UNION ALL SELECT 'SUPPLIERS', COUNT(*), 4 FROM SUPPLIERS
UNION ALL SELECT 'WORKSHOPS', COUNT(*), 2 FROM WORKSHOPS
UNION ALL SELECT 'SERVICES', COUNT(*), 6 FROM SERVICES
UNION ALL SELECT 'FEES', COUNT(*), 7 FROM FEES
UNION ALL SELECT 'AFFILIATIONS', COUNT(*), 3 FROM AFFILIATIONS
UNION ALL SELECT 'COMPONENTS', COUNT(*), 50 FROM COMPONENTS
UNION ALL SELECT 'TIRES', COUNT(*), 7 FROM TIRES
UNION ALL SELECT 'RIMS', COUNT(*), 5 FROM RIMS
UNION ALL SELECT 'ENGINES', COUNT(*), 2 FROM ENGINES
UNION ALL SELECT 'TRANSMISSIONS', COUNT(*), 2 FROM TRANSMISSIONS
UNION ALL SELECT 'VEHICLES', COUNT(*), 8 FROM VEHICLES
UNION ALL SELECT 'CARS', COUNT(*), 6 FROM CARS
UNION ALL SELECT 'MOTORCYCLES', COUNT(*), 2 FROM MOTORCYCLES
UNION ALL SELECT 'COMPATIBILITY', COUNT(*), 114 FROM COMPATIBILITY
UNION ALL SELECT 'INVENTORY', COUNT(*), 96 FROM INVENTORY;
